package cn.qingyue.pdf;

import java.io.*;
import java.util.*;

/** Run with javac/java: real model, no Android mocks required. */
public final class NoteDocumentTest {
    private static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
    private static void reject(Runnable r,String message){try{r.run();throw new AssertionError(message);}catch(IllegalArgumentException expected){}}
    public static void main(String[] args)throws Exception{
        for(String template:new String[]{"blank","ruled","grid"})for(String size:new String[]{"A3","A4","A5","B4","B5","Letter","infinite"}){NoteDocument d=NoteDocument.create(template,size);check(d.infinite()==size.equals("infinite"),"paper size");if(!d.infinite())check(d.width>400&&d.height>d.width,"portrait paper geometry");ByteArrayOutputStream out=new ByteArrayOutputStream();NoteDocument.write(out,d);NoteDocument restored=NoteDocument.read(new ByteArrayInputStream(out.toByteArray()));check(restored.template.equals(template)&&restored.size.equals(size),"paper roundtrip");}
        NoteDocument d=NoteDocument.create("grid","infinite");d.centerX=-8000000123.125;d.centerY=14000000456.75;d.zoom=.5;d.viewportSaved=true;
        double[] points={-9000000000.5,18000000000.25,-8999999800.5,18000000100.25};
        NoteDocument.Item stroke=new NoteDocument.Item(d.newId(),NoteDocument.STROKE,0xff112233,3,points,"");d.add(stroke);points[0]=7;check(d.items().get(0).points[0]==-9000000000.5,"constructor copies coordinates");check(stroke.near(-8999999900.5,18000000050.25,1),"large negative coordinate segment hit");check(!stroke.near(0,0,1),"distant segment missed");
        NoteDocument.Item image=new NoteDocument.Item(d.newId(),NoteDocument.IMAGE,0xffffffff,1,new double[]{100,100,300,200},"image_1.jpg");d.add(image);d.replace(image.bounds(-500,-700,400,200));check(d.find(image.id).left()==-500,"image moves and resizes");check(d.undo()&&d.find(image.id).left()==100,"undo image transform");check(d.redo()&&d.find(image.id).left()==-500,"redo image transform");
        NoteDocument.Item text=new NoteDocument.Item(d.newId(),NoteDocument.TEXT,0xff123456,20,new double[]{20,30,220,90},"","中文 English\n第二行");d.add(text);check(text.near(40,40,0),"text selection");check(d.copy().find(text.id).text.equals(text.text),"copy retains text");check(NoteDocument.eraseSweep(Collections.singletonList(text),30,30,40,40,5).get(0)==text,"eraser keeps text");d.replace(text.bounds(40,50,240,70));check(d.undo()&&d.find(text.id).left()==20,"undo text move");check(d.redo()&&d.find(text.id).right()==280,"redo text width");NoteDocument.Item resized=new NoteDocument.Item(text.id,NoteDocument.TEXT,text.color,32,new double[]{40,50,300,150},"",text.text);d.replace(resized);check(d.find(text.id).width==32&&d.find(text.id).right()==300,"text font and box resize");check(d.undo()&&d.find(text.id).width==20,"undo text font resize");check(d.redo()&&d.find(text.id).width==32,"redo text font resize");ByteArrayOutputStream textBytes=new ByteArrayOutputStream();NoteDocument.write(textBytes,d);NoteDocument reopened=NoteDocument.read(new ByteArrayInputStream(textBytes.toByteArray()));check(reopened.find(text.id).text.equals(text.text)&&reopened.find(text.id).width==32,"text and size survive reopen");d.remove(text.id);check(d.find(text.id)==null,"text deletion");check(d.undo()&&d.find(text.id)!=null,"undo text deletion");check(d.redo()&&d.find(text.id)==null,"redo text deletion");
        String sourceUri="qingyue://source?v=1&doc=123&page=2";NoteDocument sourceNote=NoteDocument.create("blank","A4");NoteDocument.Item sourceText=new NoteDocument.Item(sourceNote.newId(),NoteDocument.TEXT,0xff123456,17,new double[]{20,30,320,100},sourceUri,"来源 · 文档 · 第 3 页");sourceNote.add(sourceText);sourceNote.replace(sourceText.bounds(35,60,300,80));check(sourceNote.find(sourceText.id).image.equals(sourceUri),"move keeps source");sourceNote.replace(sourceNote.find(sourceText.id).withText("编辑后的摘录",20,0xff123456,90));check(sourceNote.find(sourceText.id).image.equals(sourceUri),"edit keeps source");ByteArrayOutputStream sourceBytes=new ByteArrayOutputStream();NoteDocument.write(sourceBytes,sourceNote);check(NoteDocument.read(new ByteArrayInputStream(sourceBytes.toByteArray())).find(sourceText.id).image.equals(sourceUri),"source persists");sourceNote.remove(sourceText.id);check(sourceNote.undo()&&sourceNote.find(sourceText.id).image.equals(sourceUri),"undo delete restores source");reject(()->new NoteDocument.Item(1,NoteDocument.TEXT,0,17,new double[]{0,0,300,80},"https://external.example/", "bad"),"external source accepted");
        reject(()->new NoteDocument.Item(1,NoteDocument.TEXT,0xff000000,20,new double[]{0,0,200,60},"",""),"empty text accepted");reject(()->new NoteDocument.Item(1,NoteDocument.TEXT,0xff000000,20,new double[]{0,0,20,60},"","x"),"narrow text accepted");
        ByteArrayOutputStream legacyBytes=new ByteArrayOutputStream();DataOutputStream legacy=new DataOutputStream(legacyBytes);legacy.writeInt(0x514e4f54);legacy.writeInt(1);legacy.writeUTF("blank");legacy.writeUTF("A4");legacy.writeBoolean(false);legacy.writeDouble(0);legacy.writeDouble(0);legacy.writeDouble(1);legacy.writeInt(1);legacy.writeLong(1);legacy.writeInt(NoteDocument.STROKE);legacy.writeInt(0xff000000);legacy.writeFloat(2);legacy.writeUTF("");legacy.writeInt(2);legacy.writeDouble(4);legacy.writeDouble(5);legacy.flush();NoteDocument oldNote=NoteDocument.read(new ByteArrayInputStream(legacyBytes.toByteArray()));check(oldNote.items().get(0).type==NoteDocument.STROKE,"v1 note opens");ByteArrayOutputStream upgradedBytes=new ByteArrayOutputStream();NoteDocument.write(upgradedBytes,oldNote);check(NoteDocument.read(new ByteArrayInputStream(upgradedBytes.toByteArray())).items().get(0).points[0]==4,"v1 note upgrades to v2 without losing ink");
        d.remove(image.id);check(d.find(image.id)==null,"image deletion");d.undo();check(d.find(image.id)!=null,"undo image deletion");d.undo();d.add(new NoteDocument.Item(d.newId(),NoteDocument.LINE,0xff000000,2,new double[]{0,0,10,10},""));check(!d.canRedo(),"new action clears redo");
        for(int type:new int[]{NoteDocument.CIRCLE,NoteDocument.RECTANGLE,NoteDocument.ARROW})d.add(new NoteDocument.Item(d.newId(),type,0xff123456,2,new double[]{10,10,110,110},""));
        NoteDocument.Item arrow=new NoteDocument.Item(42,NoteDocument.ARROW,0xff000000,2,new double[]{0,0,100,0},"");double[] heads=NoteDocument.arrowHeads(arrow.points,arrow.width);check(arrow.near(heads[0],heads[1],.2),"arrow head outside endpoint bounds erases");check(arrow.top()<0&&arrow.bottom()>0,"arrow head included in viewport culling bounds");
        NoteDocument.Item circle=new NoteDocument.Item(40,NoteDocument.CIRCLE,0xff000000,2,new double[]{0,0,100,100},"");check(circle.near(100,50,.1),"circle perimeter hit");check(!circle.near(50,50,.1),"circle center is not ink");NoteDocument.Item rectangle=new NoteDocument.Item(41,NoteDocument.RECTANGLE,0xff000000,2,new double[]{100,100,0,0},"");check(rectangle.near(0,50,.1),"reverse rectangle geometry");check(!rectangle.near(50,50,.1),"rectangle center is not ink");
        NoteDocument erasing=NoteDocument.create("blank","infinite");
        erasing.add(new NoteDocument.Item(erasing.newId(),NoteDocument.STROKE,0xff2468ac,4,new double[]{0,0,100,0},""));
        erasing.add(new NoteDocument.Item(erasing.newId(),NoteDocument.IMAGE,0xffffffff,1,new double[]{40,-10,60,10},"image_1.jpg"));
        List<NoteDocument.Item> partial=NoteDocument.eraseSweep(erasing.items(),50,-10,50,10,3);
        check(partial.size()>=3&&partial.get(partial.size()-1).type==NoteDocument.IMAGE,"local eraser retains both stroke sides and images");
        check(partial.get(0).type==NoteDocument.STROKE&&partial.get(0).color==0xff2468ac&&partial.get(0).width==4,"eraser retains ink styling");
        check(erasing.applyErasure(partial)&&erasing.items().size()==partial.size(),"one gesture commits fragments");
        check(erasing.undo()&&erasing.items().size()==2,"one undo restores entire stroke");
        check(erasing.redo()&&erasing.items().size()==partial.size(),"redo restores all fragments");
        ByteArrayOutputStream erasedBytes=new ByteArrayOutputStream();NoteDocument.write(erasedBytes,erasing);
        check(NoteDocument.read(new ByteArrayInputStream(erasedBytes.toByteArray())).items().size()==partial.size(),"erased fragments survive reopen");
        NoteDocument shapeErase=NoteDocument.create("blank","infinite");
        shapeErase.add(new NoteDocument.Item(shapeErase.newId(),NoteDocument.RECTANGLE,0xff778899,5,new double[]{0,0,100,100},""));
        List<NoteDocument.Item> shapePieces=NoteDocument.eraseSweep(shapeErase.items(),50,-3,50,3,2);
        check(shapePieces.size()==1&&shapePieces.get(0).type==NoteDocument.STROKE&&shapePieces.get(0).width==5,"partially erased shape becomes one styled open path across its seam");
        NoteDocument.Item fadedCircle=new NoteDocument.Item(2,NoteDocument.CIRCLE,0x55224488,3,new double[]{0,0,100,100},"");
        List<NoteDocument.Item> circlePieces=NoteDocument.eraseSweep(Collections.singletonList(fadedCircle),0,50,5,50,2);
        check(circlePieces.size()==1&&circlePieces.get(0).color==0x55224488,"Circle seam duplicated translucent ink");
        NoteDocument longLine=NoteDocument.create("blank","infinite");
        longLine.add(new NoteDocument.Item(longLine.newId(),NoteDocument.STROKE,0x66224488,.2f,new double[]{-100000,0,100000,0},""));
        List<NoteDocument.Item> thinCut=NoteDocument.eraseSweep(longLine.items(),.1,-1,.1,1,.1);
        check(thinCut.size()==2&&thinCut.get(0).points.length==4&&thinCut.get(1).points.length==4,"Tiny eraser missed or oversampled long infinite-canvas line");
        List<NoteDocument.Item> secondCut=NoteDocument.eraseSweep(thinCut,50000,-1,50000,1,.1);
        check(secondCut.size()==3,"Second pass did not split retained long line");
        NoteDocument.Item fadedArrow=new NoteDocument.Item(1,NoteDocument.ARROW,0x55336699,3,new double[]{0,0,100,0},"");
        List<NoteDocument.Item> arrowPieces=NoteDocument.eraseSweep(Collections.singletonList(fadedArrow),50,-5,50,5,2);
        check(arrowPieces.size()==4,"Arrow shaft cut should retain two shaft parts and two independent heads");
        for(NoteDocument.Item piece:arrowPieces)check(piece.color==0x55336699&&piece.points.length==4,"Arrow alpha changed or head retraced");
        ByteArrayOutputStream encoded=new ByteArrayOutputStream();NoteDocument.write(encoded,d);NoteDocument restored=NoteDocument.read(new ByteArrayInputStream(encoded.toByteArray()));check(restored.items().size()==d.items().size(),"all item types preserved");check(restored.centerX==d.centerX&&restored.centerY==d.centerY&&restored.zoom==d.zoom&&restored.viewportSaved,"viewport double precision persists");check(restored.items().get(0).points[0]==-9000000000.5,"infinite canvas coordinate persistence");long max=0;for(NoteDocument.Item item:restored.items())max=Math.max(max,item.id);check(restored.newId()>max,"new ids after reopen");
        byte[] truncated=Arrays.copyOf(encoded.toByteArray(),encoded.size()-1);try{NoteDocument.read(new ByteArrayInputStream(truncated));throw new AssertionError("truncation accepted");}catch(IOException expected){}
        byte[] trailing=Arrays.copyOf(encoded.toByteArray(),encoded.size()+1);try{NoteDocument.read(new ByteArrayInputStream(trailing));throw new AssertionError("trailing bytes accepted");}catch(IOException expected){}
        reject(()->new NoteDocument.Item(1,NoteDocument.IMAGE,0,1,new double[]{0,0,1,1},"../secret.jpg"),"image path traversal accepted");reject(()->new NoteDocument.Item(1,NoteDocument.STROKE,0,1,new double[]{Double.NaN,0},""),"NaN accepted");reject(()->NoteDocument.create("unknown","A4"),"unknown paper accepted");
        NoteDocument snapshot=d.copy();d.remove(d.items().get(0).id);check(snapshot.items().size()==d.items().size()+1,"snapshot independent from undo/edit lists");
        NoteDocument multi=NoteDocument.create("ruled","A4");multi.add(new NoteDocument.Item(multi.newId(),NoteDocument.STROKE,0xff000000,2,new double[]{1,2,3,4},""));multi.centerX=123;multi.viewportSaved=true;multi.addPage();multi.add(new NoteDocument.Item(multi.newId(),NoteDocument.TEXT,0xff123456,18,new double[]{20,30,220,90},sourceUri,"第二页来源"));multi.centerY=456;multi.viewportSaved=true;multi.addPage();multi.movePage(2,1);check(multi.pageCount()==3&&multi.currentPage()==1,"page creation and reorder");multi.selectPage(0);check(multi.items().get(0).points[0]==1&&multi.centerX==123,"page contents and viewport restored");multi.selectPage(2);check(multi.items().get(0).text.equals("第二页来源")&&multi.centerY==456,"reordered text page restored");ByteArrayOutputStream pagesBytes=new ByteArrayOutputStream();NoteDocument.write(pagesBytes,multi);NoteDocument pagesRestored=NoteDocument.read(new ByteArrayInputStream(pagesBytes.toByteArray()));check(pagesRestored.pageCount()==3&&pagesRestored.currentPage()==2&&pagesRestored.items().get(0).image.equals(sourceUri),"v3 pages and source survive reopen");pagesRestored.selectPage(0);check(pagesRestored.items().get(0).points[0]==1,"first page ink survives reopen");
        ByteArrayOutputStream v2bytes=new ByteArrayOutputStream();DataOutputStream v2=new DataOutputStream(v2bytes);v2.writeInt(0x514e4f54);v2.writeInt(2);v2.writeUTF("grid");v2.writeUTF("A5");v2.writeBoolean(true);v2.writeDouble(12);v2.writeDouble(34);v2.writeDouble(1.25);v2.writeInt(1);v2.writeLong(9);v2.writeInt(NoteDocument.TEXT);v2.writeInt(0xff123456);v2.writeFloat(17);v2.writeUTF(sourceUri);v2.writeInt(4);for(double coordinate:new double[]{10,20,210,90})v2.writeDouble(coordinate);v2.writeUTF("旧版来源");v2.flush();NoteDocument v2read=NoteDocument.read(new ByteArrayInputStream(v2bytes.toByteArray()));check(v2read.pageCount()==1&&v2read.items().get(0).text.equals("旧版来源")&&v2read.items().get(0).image.equals(sourceUri)&&v2read.centerX==12,"v2 text/source migrates losslessly");
        NoteDocument history=NoteDocument.create("blank","A4");history.add(new NoteDocument.Item(history.newId(),NoteDocument.STROKE,0xff000000,2,new double[]{1,1,2,2},""));history.addPage();history.add(new NoteDocument.Item(history.newId(),NoteDocument.STROKE,0xff000000,2,new double[]{3,3,4,4},""));check(history.undo()&&history.items().isEmpty(),"undo affects active page");history.selectPage(0);check(history.items().size()==1&&!history.canUndo(),"switching pages cannot undo ink on another page");
        System.out.println("NoteDocumentTest passed: 21 paper/template combinations, two-axis coordinates, vector shapes, image geometry, undo/redo, serialization and corrupt data rejection.");
    }
}
